    /** Picks one entry by weight, skipping the horror ones (hr...) unless allowed; "none"-like first entries are kept when no weight is set. */
    static String pick(String[] keys, double[] w, LyricKit.Rng r, boolean horror) {
        double sum = 0;
        for (int i = 0; i < keys.length; i++) if (horror || !keys[i].startsWith("hr")) sum += Math.max(0.01, w[i]);
        double x = r.next() * sum;
        for (int i = 0; i < keys.length; i++) {
            if (!horror && keys[i].startsWith("hr")) continue;
            x -= Math.max(0.01, w[i]);
            if (x <= 0) return keys[i];
        }
        return keys[0];
    }
